{
  "probability": 0.01,
  "range_low": 0.01,
  "range_high": 0.03,
  "summary": [
    "Bayesian posterior for AfD winning the most seats in Baden-Württemberg is about 1%.",
    "Anchor set by reference class: Baden-Württemberg Landtag elections where AfD has not been the largest party; historical leaders were CDU or Greens.",
    "Credible polls late Jan–Feb 2026 show CDU and Greens ahead of AfD (AfD around 18–21%), reinforcing the unlikely lead for AfD.",
    "Rare late-2025 uptick where AfD briefly overtook Greens exists but current data keeps the chance very small and coalition norms discourage AfD as largest party."
  ],
  "confidence": "low",
  "narrative": "Starting from a conservative base rate given the reference class and incorporating recent credible polling data, the probability that AfD wins the most seats in Baden-Württemberg is about 1%. The occasional late-2025 uptick is insufficient to overcome the prevailing CDU/Greens lead and coalition dynamics.",
  "justification": {
    "anchor": {
      "probability": 0.35,
      "basis": "reference-class choice: state-level Baden-Württemberg elections where AfD has not led; aligns with historically low baseline for AfD to be largest in this state."
    },
    "factor_updates": [
      {
        "factor": "CDU leads in credible polls; AfD not the largest party",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Jan–Feb 2026 polls place CDU ~27–29%, Greens ~23–27%, AfD ~18–21%, implying AfD not the largest party."
      },
      {
        "factor": "Occasional cross-over where AfD overtook Greens (Oct 2025)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Momentum spike in Oct 2025 shows potential upside for AfD if trend persists, offset by more recent data."
      },
      {
        "factor": "AfD polling around 18–20% in Feb 2026",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Late-Feb 2026 Infratest dimap shows AfD 18–20%, behind CDU and Greens."
      },
      {
        "factor": "No historical instance of AfD leading Baden-Württemberg",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Reference class baseline lowers probability of AfD leading a Landtag."
      }
    ],
    "synthesis_rationale": "The posterior is a convergence of a strong negative anchor from credible polls and a long-run historical baseline, with a single smaller positive shock from late-2025 upticks. Given correlation among polls and baseline, the net effect yields a very low probability (~1%). No calibration adjustment raised the final estimate; the result reflects a cautious, conservative synthesis recognizing coalition dynamics and turnout risks."
  }
}

{
  "probability": 0.01,
  "range_low": 0.01,
  "range_high": 0.03,
  "summary": [
    "Anchor from base-rate: AfD has historically not led BW Landtags and polls early in 2026 show CDU ahead or closely ahead of Greens, with AfD well behind.",
    "Most credible polls (Jan–Feb 2026) place CDU around high-20s to ~29%, Greens in the mid-20s, and AfD around 18–21%, making AfD unlikely to be the largest party.",
    "A late-2025 uptick where AfD briefly overtook Greens suggests some volatility but did not sustain into February 2026 data.",
    "Historical absence of AfD-led BW Landtags and coalition dynamics further reduce practical chances of AfD being the largest party."
  ],
  "confidence": "low",
  "narrative": "Starting from a modest base-rate anchor, recent pre-election polls show CDU or Greens ahead of AfD, with AfD polling in the high-teens to about 20%. When combined with historical patterns and coalition realities, the probability that AfD wins the most seats in Baden-Württemberg in 2026 lands at about 1%.",
  "justification": {
    "anchor": {
      "probability": 0.05,
      "basis": "reference-class anchor based on historical absence of AfD as largest party in BW and early-2026 polling indicating CDU/Greens ahead."
    },
    "factor_updates": [
      {
        "factor": "CDU lead remains credible in recent polls",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Jan–Feb 2026 polls place CDU around 27–29%, Greens 23–27%, AfD 18–21%, reducing AfD's chances of leading."
      },
      {
        "factor": "Occasional cross-over where AfD overtook Greens (late-2025 window)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Transient momentum could boost AfD, but current data show CDU/Greens still ahead."
      },
      {
        "factor": "AfD polling around 18–20% in Feb 2026",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Late-February data place AfD well behind both CDU and Greens, limiting its lead potential."
      },
      {
        "factor": "No historical instance of AfD leading a BW Landtag",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Long-run pattern reduces baseline probability of AfD being largest."
      }
    ],
    "synthesis_rationale": "Starting from a 5% anchor, the weight of current credible polls showing CDU/Greens ahead and AfD around 18–21%—coupled with historical norms—drives a steep downward revision. The posterior of 1% reflects the combination of present data and the low probability of a late, coalitions-be-droken shift that would elevate AfD to the top seat share, acknowledging possible but unlikely tail-risk."
  }
}

